pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    SigMaker maker;

    function setUp() public {
        c = new C("", 0, address(this));
        maker = new SigMaker();
    }

    function testFuzz_property(uint256 nonce, uint256 duration, address recipient) public {
        vm.assume(recipient != address(0) && recipient != address(this) && recipient != address(c));
        duration = bound(duration, 0, 9_999 days);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(c),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: block.timestamp + 1,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory emptyIds = new uint256[](0);
        uint256 positionId = c.fillOrder(order, "", emptyIds);

        // first transfer of our position token by its owner (this test contract)
        c.transferFrom(address(this), recipient, positionId);

        // general rule: after a successful transfer, the previous owner can no longer transfer it
        bool ok;
        try c.transferFrom(address(this), recipient, positionId) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract SigMaker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(
        uint256 makerKey,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        address filler1,
        address filler2
    ) public {
        vm.assume(makerKey != 0);
        vm.assume(filler1 != address(0) && filler2 != address(0) && filler1 != filler2);
        vm.assume(uint256(uint160(filler1)) > 10 && uint256(uint160(filler2)) > 10);
        strike = bound(strike, 1, type(uint128).max);
        premium = bound(premium, 0, type(uint128).max);
        duration = bound(duration, 1, 9_000 days);

        address maker = vm.addr(makerKey);
        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: true,
            isLong: true,
            baseAsset: address(this),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(makerKey, orderHash);
        bytes memory signature = abi.encodePacked(r, s, v);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        vm.prank(filler1);
        c.fillOrder(order, signature, floorAssetTokenIds);

        uint256 oppositeId = uint256(c.hashOppositeOrder(order));

        vm.prank(filler2);
        c.fillOrder(order, signature, floorAssetTokenIds);

        assertEq(c.ownerOf(oppositeId), filler1);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    uint256 constant MAKER_PK = 0xA11CE;
    address maker;

    function setUp() public {
        c = new C("", 0, address(this));
        maker = vm.addr(MAKER_PK);
    }

    function testFuzz_property(uint256 strike, uint256 premium, uint256 duration, address recipient, uint256 warpTime) public {
        // keep params in the admissible domain (wide)
        vm.assume(recipient != address(0) && recipient != maker);
        strike = bound(strike, 0, 1e30);
        premium = bound(premium, 0, 1e30);
        duration = bound(duration, 1 days, 9_000 days);
        warpTime = bound(warpTime, 1, 1_000_000);

        vm.warp(warpTime);

        // build a valid, signable order so a position token gets minted to maker
        C.Order memory order;
        order.maker = maker;
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(c); // c has code, satisfies baseAsset check; premium/strike are 0-ish paths
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = block.timestamp + 10_000 days;
        order.nonce = 0;

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(MAKER_PK, orderHash);
        bytes memory signature = abi.encodePacked(r, s, v);

        uint256[] memory noFloor = new uint256[](0);

        vm.prank(maker);
        c.fillOrder(order, signature, noFloor);

        uint256 tokenId = uint256(orderHash);
        vm.assume(c.ownerOf(tokenId) == maker); // token minted to maker

        // drive the mutated unit: c.transferFrom, as a SELF-transfer by the owner
        uint256 balBefore = c.balanceOf(maker);

        vm.prank(maker);
        c.transferFrom(maker, maker, tokenId);

        // General rule: a transferFrom of a token to its current owner (self-transfer)
        // must not change the owner's token balance — the sender's balance is debited
        // exactly as the recipient's is credited.
        assertTrue(c.balanceOf(maker) == balBefore, "self-transfer must not change owner balance");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    MockERC20 token;
    ERC1271Signer signer;

    function setUp() public {
        c = new C("", 0, address(this));
        token = new MockERC20();
        signer = new ERC1271Signer();
    }

    function testFuzz_property(uint256 strike, uint256 duration, uint256 nonce) public {
        vm.assume(strike < 2 ** 128);
        duration = bound(duration, 1, 9999 days);

        C.Order memory order;
        order.maker = address(signer);
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(token);
        order.strike = strike;
        order.premium = 0;
        order.duration = duration;
        order.expiration = block.timestamp + 1;
        order.nonce = nonce;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new C.ERC20Asset[](0);
        order.erc721Assets = new C.ERC721Asset[](0);

        uint256[] memory noFloorIds = new uint256[](0);

        // Fill the order: mints the long position token to this test contract.
        c.fillOrder(order, "", noFloorIds);

        uint256 positionId = uint256(c.hashOppositeOrder(order));

        uint256 balBefore = c.balanceOf(address(this));

        // Self-transfer of the owned token must conserve the owner's balance.
        c.transferFrom(address(this), address(this), positionId);

        assertTrue(balBefore == c.balanceOf(address(this)));
    }
}

contract ERC1271Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address, address, uint256) external returns (bool) {
        return true;
    }

    function transfer(address, uint256) external returns (bool) {
        return true;
    }
}
